    "author": "",
    "description": "中新网9月17日电 据“美丽东兰”微信公众号消息，广西东兰县应急管理局9月17日发布情况说明表示，近日，网络上流传视频信息称“7月21日，广西东兰县红水河发生洪灾导致30人被困”。经东兰县应急管理局与气象局、水利局以及相关乡镇进行调查核实，东兰县境内未发生过30人被困的洪涝灾害情况。网传内容与实际情况严重不符，视频画面为剪辑拼接、AI生成，并非东兰县本地真实场景，属于不实信息。请广大网民不信谣、不传谣、不造谣，共同维护清朗的网络空间。",
    "content": "中新网9月17日电 据“美丽东兰”微信公众号消息，广西东兰县应急管理局9月17日发布情况说明表示，近日，网络上流传视频信息称“7月21日，广西东兰县红水河发生洪灾导致30人被困”。经东兰县应急管理局与气象局、水利局以及相关乡镇进行调查核实，东兰县境内未发生过30人被困的洪涝灾害情况。网传内容与实际情况严重不符，视频画面为剪辑拼接、AI生成，并非东兰县本地真实场景，属于不实信息。请广大网民不信谣、不传谣、不造谣，共同维护清朗的网络空间。"
