    "author": "吴梦桐,董雪",
    "description": "新华社北京9月17日电（记者吴梦桐、董雪）联合国人权理事会第63届会议期间，中方和联合国日内瓦办事处在日内瓦万国宫共同举办“人人享有无障碍”主题展览。外交部发言人郭嘉昆17日表示，举办此次展览是落实“无障碍建设促进所有人享有人权”决议的重要举措。中国将向本届理事会再次主提无障碍决议，并同国际社会一道，不断丰富人权保障实践，推动完善全球人权治理。 郭嘉昆介绍，这场主题展览吸引了300多位嘉宾出席，包括联合国人权事务高级专员图尔克、各国常驻…",
    "content": "新华社北京9月17日电（记者吴梦桐、董雪）联合国人权理事会第63届会议期间，中方和联合国日内瓦办事处在日内瓦万国宫共同举办“人人享有无障碍”主题展览。外交部发言人郭嘉昆17日表示，举办此次展览是落实“无障碍建设促进所有人享有人权”决议的重要举措。中国将向本届理事会再次主提无障碍决议，并同国际社会一道，不断丰富人权保障实践，推动完善全球人权治理。 郭嘉昆介绍，这场主题展览吸引了300多位嘉宾出席，包括联合国人权事务高级专员图尔克、各国常驻代表、国际组织负责人、媒体代表等。展览从科技、文化、就业、法治等角度全方位展现中…"
