    "content": "&nbsp; 9月16日，新中国成立以来 我国第一条国家层面统筹建设的通江达海运河工程——平陆运河建成通航 平陆运河总投资约727亿元 全长134.2公里 北起南宁横州市西津库区平塘江口 沿钦江直通北部湾 可通航5000吨级船舶 平陆运河通航后 西南地区货物经运河出海较经传统路径缩短内河航程560公里以上 每年可为社会节约运输费用超50亿元 2022年8月28日开工建设以来 不断刷新中国运河建设速度 并取得1项世界首创 4项世界之最 让我们从跨越四年的卫星图对比来观察运河建设前后的变化 2022年10月，广西平陆运…"
