    "description": "中新网银川9月17日电 (记者 李佩珊)9月17日，以“红色六盘承初心 长征精神薪火传”为主题的第四届六盘山红色文化旅游节在宁夏固原隆德县启幕。本次节会立足固原全域革命老区红色资源优势，以文塑旅、以旅兴产，推动红色资源与生态文旅、乡村振兴、特色产业深度融合，全方位展现六盘山红色文脉与革命老区发展新貌。",
