    "content": "“某某孩子妈妈您好，孩子要升初三了……”近段时间，不少家长频频收到这类骚扰电话。一些家长发现，来电者不仅知道自己号码，还能准确说出孩子的姓名、学校甚至年级、班级。 一家长的微信截图显示，机构能准确说出孩子的姓名和年级。（受访者供图） “新华视点”记者调查发现，从信息收集到加工转卖，再到精准营销，围绕学生个人信息潜藏一条黑灰利益链。 骚扰电话精准说出孩子信息 “明明没留手机号码，但电话总是频繁打过来。”北京一小学三年级学生家长程女士说，近期接到大量培训机构的电话，拉黑一个又来一个，看到陌生号码都不敢接。 不少家长反映…"
