    "title": "秋季开学，专家提示警惕诺如病毒“吐”然来袭",
    "link": "http://www.news.cn/20260917/25a23321bb05421a93878660166755e2/c.html",
    "pub_date": "2026-09-17 17:55:45",
    "author": "王烁",
    "description": "新华社郑州9月17日电（记者王烁）秋季开学，随着孩子们重返校园，诺如病毒也进入高发期。每年10月至次年3月是诺如病毒流行高峰，学校、托幼机构等人员密集场所易发生聚集性疫情。河南省疾控中心专家提示，公众需从洗手、消毒、吐泻物处理、环境清洁等方面做好科学防护。 河南省疾控中心传染病所副主任技师李懿表示，诺如病毒是引起急性胃肠炎的常见病原体，具有传染性强、传播途径多、人群普遍易感等特点。感染后最常见症状为突发的恶心、呕吐、腹痛、腹泻（通常为水…",
    "content": "新华社郑州9月17日电（记者王烁）秋季开学，随着孩子们重返校园，诺如病毒也进入高发期。每年10月至次年3月是诺如病毒流行高峰，学校、托幼机构等人员密集场所易发生聚集性疫情。河南省疾控中心专家提示，公众需从洗手、消毒、吐泻物处理、环境清洁等方面做好科学防护。 河南省疾控中心传染病所副主任技师李懿表示，诺如病毒是引起急性胃肠炎的常见病原体，具有传染性强、传播途径多、人群普遍易感等特点。感染后最常见症状为突发的恶心、呕吐、腹痛、腹泻（通常为水样便），有时伴有发热、头痛、肌肉酸痛等。 李懿在野外工作。新华社发 “保持良好的…"
