    "content": "@极目新闻 9月17日消息，近日，吉林农业科技学院左家校区的班级群流传一张聊天截图，学生在群里发通知称，学校附近发现老虎，提醒大家晚上不要在外逗留，注意安全。 9月17日，记者从当地获悉，这是吉林市昌邑区左家镇政府发布的紧急通知，该高校收到后发布在班级学生群。东北虎出没区域在校区10公里之外，学校已加强巡逻和安保防范，严格执行学生管理制度。 该聊天截图内容显示，通知称，白庙子村（距学校直线距离8.2公里）发现老虎，请实习、劳动课的老师高度重视，无课教师尽量不要去沙家沟水库。同时，请大家最近早点回寝室，晚上不要在外面…"
