    "content": "Anthropic在呼吁放慢前沿人工智能（AI）发展速度的同时，仍在持续扩大AI基础设施布局。 当地时间9月16日，据外媒报道，Anthropic已签署其在澳大利亚的首份数据中心租赁协议，将获得一座总规划容量达2.16吉瓦（GW）的数据中心园区。该项目尚需等待澳大利亚外国投资审查委员会批准，预计最快于2027年起投入运营。 知情人士称，新的数据中心将主要用于AI推理，即处理用户请求、生成预测结果等运行阶段的计算，而不会用于模型训练。该项目由数据中心开发商Zerra DC负责，计划通过可再生能源购电协议获取电力，并自…"
