    "content": "日前，国务院办公厅印发《关于进一步加强烟花爆竹全链条安全监管的意见》（以下简称《意见》），对防范化解重大安全风险，有效遏制事故发生作出部署。 《意见》强调，要坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会精神，坚持人民至上、生命至上，统筹发展和安全，聚焦突出问题，压实企业主体责任、部门监管责任、属地管理责任，提升烟花爆竹行业本质安全水平。 《意见》提出加强烟花爆竹生产、储存、经营、运输、燃放等各环节全链条安全监管的一系列具体措施。生产环节要严格生产企业准入许可审批，强化烟花爆竹生产…"
