    "content": "新华社济南9月17日电（记者张力元）在山东大学齐鲁交通学院，建成通车不久的济南黄岗路黄河隧道，已从一项超级工程转变为师生研究工程机器人的鲜活案例。 教室屏幕上，开挖直径17.5米的“山河号”盾构机缓缓向前，前方地质特征、刀具磨损状态、同步注浆质量等数据不断变化。岩土工程专业研二学生温正明认真记下关键参数。他说：“以前觉得盾构机主要是机械设备，通过学习发现，地质、传感、人工智能都能用上。” 今年暑期，山东大学智能建造与智慧交通（工程机器人新工科实验班）培养方案通过论证，越来越多的真实工程难题融入课程教学，“山河号”就…"
