    "author": "丛磊",
    "description": "9月17日，国务院新闻办公室举行“新征程上的奋斗者”中外记者见面会，请驻村第一书记代表围绕“肩负使命，在乡村振兴一线实干”与中外记者见面交流。河北省张家口市阳原县辛堡乡四十亩村驻村第一书记孙国亮表示，驻村期满不回城，在村里一待就是十多年，支撑他留下来的是与乡亲们处出来的真情，肩上放不下的责任，还有组织的信任。 新华社音视频部制作",
