    "content": "新华社北京9月17日电（记者樊曦）记者从中铁二十五局集团有限公司了解到，17日，广西滨海公路长坜立交桥成功完成转体施工，顺利跨越钦防高铁与南防铁路两条铁路线，为全线如期建成通车奠定坚实基础。 长坜立交桥位于广西防城港市茅岭镇，是广西滨海公路全线重难点工程。其转体段长158米，宽39.4米，采用双幅T构转体梁设计，面积相当于约14个标准篮球场大小，转体总重量达3.6万吨。 为确保钦防高铁与南防铁路正常运营，建设团队采用平行于铁路建桥，再充分利用暂时没有列车行驶的“天窗”时间旋转桥体的方式进行转体施工。针对大体量转体施…"
