    "description": "新华社堪培拉9月17日电（记者王佳琳）澳大利亚内政部长托尼·伯克17日宣布，政府将收紧留学生家属签证并调整打工度假签证等政策，以削减移民规模。 伯克当天在堪培拉表示，政府计划将本财年海外净移民人数降至24.5万人，2027至2028财年进一步降至22.5万人。 根据新规，留学生将不再自动享有携家属赴澳的资格。家属已附属于其签证下的在澳留学生、来自太平洋岛国和东盟国家的留学生以及博士生将获豁免。澳政府数据显示，2025至2026财年，澳大…",
    "content": "新华社堪培拉9月17日电（记者王佳琳）澳大利亚内政部长托尼·伯克17日宣布，政府将收紧留学生家属签证并调整打工度假签证等政策，以削减移民规模。 伯克当天在堪培拉表示，政府计划将本财年海外净移民人数降至24.5万人，2027至2028财年进一步降至22.5万人。 根据新规，留学生将不再自动享有携家属赴澳的资格。家属已附属于其签证下的在澳留学生、来自太平洋岛国和东盟国家的留学生以及博士生将获豁免。澳政府数据显示，2025至2026财年，澳大利亚共批准约33.7万份学生签证，其中约4.6万份发给主申请人的附属申请人。 伯…"
