    "content": "GPT-6 Astra 生成 3D 的输出是 GLB ，带 PBR 贴图，网页里转着看很漂亮——但切片软件不吃这个格式。Bambu Studio 、PrusaSlicer 、Cura 认的是 STL / 3MF / OBJ / STEP ，没有一个收 GLB 。想打印就得先转。 麻烦的是这不是改个后缀的事。glTF 规范规定 Y 轴朝上、单位是米； STL 既不带坐标轴也不带单位，全靠读的人猜。所以一个 GLB 走了不处理这层的工具，出来的模型是躺着的，而且小 1000 倍——1 米被当成 1 毫米。 在线转换那些…"
