    "title": "[分享创造] Chupin：把简历做成一页网页，需要文件时再导出 PDF",
    "link": "https://www.v2ex.com/t/1242743#reply0",
    "pub_date": "2026-09-17 16:21:10",
    "author": "ilikexff",
