    "author": "龚雯",
    "description": "新华社上海9月17日电（记者龚雯）记者17日从上海市政府新闻发布会上获悉，由上海市人民政府、联合国教科文组织共同主办的2026年世界设计之都大会将于9月28日至30日召开，主会场设在上海市黄浦区。其中，主场展览将于9月26日提前向公众开放。 上海自2010年加入联合国创意城市网络，今年即将迎来第5届世界设计之都大会，包含开幕式、主展览、工业文化发展大会以及系列论坛和活动。 今年大会将紧扣智能化、绿色化设计发展趋势，汇聚近千名国内外专家学…",
    "content": "新华社上海9月17日电（记者龚雯）记者17日从上海市政府新闻发布会上获悉，由上海市人民政府、联合国教科文组织共同主办的2026年世界设计之都大会将于9月28日至30日召开，主会场设在上海市黄浦区。其中，主场展览将于9月26日提前向公众开放。 上海自2010年加入联合国创意城市网络，今年即将迎来第5届世界设计之都大会，包含开幕式、主展览、工业文化发展大会以及系列论坛和活动。 今年大会将紧扣智能化、绿色化设计发展趋势，汇聚近千名国内外专家学者、产业领军人物，研讨人工智能设计、绿色可持续设计、文化传承创新和设计之都建设。…"
