    "content": "导语：杀红眼的办公入口之争，终局刚开始。 “整个下半年，就看AI办公圈谁能杀出重围了”。一位大模型从业者对雷峰网 (公众号：雷峰网) 表示。 从五月开始，各个互联网大厂争相出场，写字楼电梯间、机场候机室，到处都是Workbuddy、千问办公、豆包工作、百度搭子的内容。 但办公大战打得再热闹，顶多算是一道前菜。 早在2025年，微软的Work Trend Index就提出过，AI进入企业分三步：帮员工做得更快、成为团队里的“数字同事”、直接执行完整的业务流程。 对照这个坐标，眼下的办公之争，其实还停在前两步。 真正难…"
