    "author": "洛卓嘉措,卢丹阳",
    "description": "地处祖国西南边陲的阿里地区，海拔高、自然条件艰苦、交通路线长。为了改善农牧民子女的学习条件，保护青少年身心健康，西藏自治区在拉萨市为阿里地区异地办学。 每到开学季，一场跨越千里的护送就此开启。8年来，阿里交警累计出动2000余人次警力，千余台次警车，行程8万公里，护送10万余名学生平安往返于这条跨越千里的求学路。 记者：洛卓嘉措、卢丹阳 部分画面来源：西藏自治区公安交通管理局 新华社音视频部制作",
    "content": "地处祖国西南边陲的阿里地区，海拔高、自然条件艰苦、交通路线长。为了改善农牧民子女的学习条件，保护青少年身心健康，西藏自治区在拉萨市为阿里地区异地办学。 每到开学季，一场跨越千里的护送就此开启。8年来，阿里交警累计出动2000余人次警力，千余台次警车，行程8万公里，护送10万余名学生平安往返于这条跨越千里的求学路。 记者：洛卓嘉措、卢丹阳 部分画面来源：西藏自治区公安交通管理局 新华社音视频部制作"
