    "content": "新华社南宁/吉隆坡9月17日电 题：东盟人士看好平陆运河拓展区域合作新空间 新华社记者赵欢 王嘉伟 平陆运河16日通航。自开工建设以来，这一连接中国广西南宁和北部湾的重要工程持续受到东盟各界关注。多位接受新华社记者采访的东盟人士认为，运河通航后，将进一步加强中国西南地区与东盟市场的联系，为区域经贸往来和产业合作创造新的连接点。 平陆运河北起南宁横州市西津库区平塘江口，南经钦州灵山县陆屋镇，沿钦江直通北部湾，全长134.2公里，可通航5000吨级船舶。作为西部陆海新通道骨干工程，平陆运河将中国西南内河航运体系与北部湾…"
